// Loads the static sample dataset generated by scripts/generate-data.mjs.
// Relative URL so it works under the GitHub Pages sub-path; same-origin (CSP connect-src 'self').

export const SAMPLE_JSON_URL = './data/requests.json';
export const SAMPLE_CSV_URL = './data/requests.csv';
export const HISTORY_CSV_URL = './data/status_history.csv';

let cache = null;

/** @returns {Promise<{meta: object, requests: object[]}>} */
export async function loadSample() {
  if (!cache) {
    cache = fetch(SAMPLE_JSON_URL, { cache: 'no-cache' }).then((res) => {
      if (!res.ok) throw new Error(`Could not load sample data (HTTP ${res.status})`);
      return res.json();
    });
    cache.catch(() => (cache = null)); // allow retry after a failure
  }
  return cache;
}

/** Count rows by a key, returned in the order of `keys` (so zero counts are kept). */
export function countBy(rows, field, keys) {
  const m = Object.fromEntries(keys.map((k) => [k, 0]));
  for (const r of rows) if (r[field] in m) m[r[field]] += 1;
  return m;
}
